"use client";

import { useState } from "react";
import Link from "next/link";

// Generated by translator/build_glossary.py. Both texts and the note are read
// from the served translation and the KJV, so nothing here is hand-written.
import translationExamples from "@/data/examples.json";

/** Render text with one phrase marked. Matching ignores case. */
function Marked({ text, phrase }: { text: string; phrase: string }) {
  const at = text.toLowerCase().indexOf(phrase.toLowerCase());
  if (at === -1) return <>{text}</>;
  return (
    <>
      {text.slice(0, at)}
      <mark className="bg-transparent text-inherit font-semibold underline decoration-amber-500 decoration-2 underline-offset-4">
        {text.slice(at, at + phrase.length)}
      </mark>
      {text.slice(at + phrase.length)}
    </>
  );
}

export function TranslationCarousel() {
  const [current, setCurrent] = useState(0);
  const example = translationExamples[current];
  const count = translationExamples.length;
  const go = (i: number) => setCurrent((i + count) % count);

  return (
    <section className="card p-6 md:p-10 mb-12" aria-label="Example verses">
      <div className="flex items-center justify-between mb-6">
        <h2 className="font-sans font-semibold text-sm uppercase tracking-wide text-neutral-500 dark:text-neutral-400">
          {example.reference}
        </h2>
        <div className="flex items-center gap-1 font-sans text-sm text-neutral-500 dark:text-neutral-400">
          <button
            onClick={() => go(current - 1)}
            className="px-2 py-1 rounded hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors"
            aria-label="Previous example"
          >
            ←
          </button>
          <span aria-live="polite">
            {current + 1} of {count}
          </span>
          <button
            onClick={() => go(current + 1)}
            className="px-2 py-1 rounded hover:bg-neutral-100 dark:hover:bg-neutral-800 transition-colors"
            aria-label="Next example"
          >
            →
          </button>
        </div>
      </div>

      {/* The two translations, side by side on wide screens */}
      <div className="grid gap-6 md:grid-cols-2 mb-8">
        <div>
          <div className="font-sans text-xs uppercase tracking-wider text-neutral-500 dark:text-neutral-400 mb-2">
            King James Version
          </div>
          <p className="text-base md:text-lg text-neutral-600 dark:text-neutral-400">
            <Marked
              text={example.traditional.text}
              phrase={example.traditional.highlight}
            />
          </p>
        </div>
        <div>
          <div className="font-sans text-xs uppercase tracking-wider text-amber-700 dark:text-amber-500 mb-2">
            AIT Bible
          </div>
          <p className="text-base md:text-lg text-neutral-900 dark:text-neutral-100">
            <Marked text={example.ait.text} phrase={example.ait.highlight} />
          </p>
        </div>
      </div>

      {/* The translation's own note on the marked words */}
      <div className="border-t border-neutral-200 dark:border-neutral-800 pt-6">
        <div className="font-sans text-xs uppercase tracking-wider text-neutral-500 dark:text-neutral-400 mb-2">
          The note on &ldquo;{example.note.term}&rdquo;
        </div>
        <p className="text-sm md:text-base text-neutral-700 dark:text-neutral-300 leading-relaxed">
          {example.note.text}
        </p>
        <p className="mt-4 font-sans text-sm">
          <Link
            href={example.href}
            className="text-amber-700 dark:text-amber-500 hover:underline font-medium"
          >
            Read {example.chapterLabel} →
          </Link>
          <span className="text-neutral-500 dark:text-neutral-400">
            {" "}
            Click any verse number there to see its notes and the Greek.
          </span>
        </p>
      </div>
    </section>
  );
}
